  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "In mice, oral administration of GTS produced slowly increasing hesperidin brain concentrations and distribution into brain tissue, demonstrating meaningful CNS access after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In NHPs, oral dosing of compound 7 achieved terminal CSF/P_u AUC ratio of 0.8 and B_u/P_u of 0.6, indicating high brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "In rhesus monkeys, GAZT poorly crossed the BBB with a mean CSF/plasma ratio of 0.04 at 1 h, providing a contradictory example of limited CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The transferred in-vivo evidence is predominantly positive across mice, rats, and NHPs, with direct brain, CSF, and unbound brain/plasma measurements supporting meaningful CNS access after systemic administration. The single low monkey CSF/plasma ratio is outweighed by multiple direct positive CNS-exposure outcomes.",
  "evidence_gaps": [
    "The contradictory record is limited to a single 1 h CSF/plasma time point in monkeys without unbound brain or multi-time data.",
    "Some supportive records are qualitative or single-timepoint, but they are consistent with the positive direction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

